    if max_attempts<=0: raise ValueError('attempts')
    count=0; state='exhausted'
    for status in statuses[:max_attempts]:
        count+=1
        if status=='success': state='succeeded'; break
        if status=='permanent': state='failed'; break
    return [count,state]

