    for start,end in sorted(spans):
        if not 0<=start<=end<=len(text): raise ValueError('span')
        if start==end: continue
        if merged and start<=merged[-1][1]: merged[-1][1]=max(end,merged[-1][1])
        else: merged.append([start,end])
    out=[]; pos=0
    for start,end in merged: out.extend([text[pos:start],'[REDACTED]']); pos=start
    out.append(text[pos:])
    return ''.join(out)

